"use client";

import React, { useState } from "react";
import SozlukEkrani from "@/components/SozlukEkrani";
import { Dialect, DictionaryMeta, ExtendedDictionaryItem } from "@/types/dictionary";

export default function Home() {
  const [loading, setLoading] = useState<boolean>(false);
  const [searchQuery, setSearchQuery] = useState<string>("");
  const [seciliLehce, setSeciliLehce] = useState<Dialect>("TUMU");
  const [seciliDosya, setSeciliDosya] = useState<string>("tumu");
  const [gununKelimesi, setGununKelimesi] = useState<ExtendedDictionaryItem | null>(null);
  const [filtrelenmisSonuclar, setFiltrelenmisSonuclar] = useState<ExtendedDictionaryItem[]>([]);
  const [aktifSozlukler, setAktifSozlukler] = useState<DictionaryMeta[]>([]);

  return (
    <SozlukEkrani
      loading={loading}
      searchQuery={searchQuery}
      setSearchQuery={setSearchQuery}
      seciliLehce={seciliLehce}
      setSeciliLehce={setSeciliLehce}
      seciliDosya={seciliDosya}
      setSeciliDosya={setSeciliDosya}
      gununKelimesi={gununKelimesi}
      filtrelenmisSonuclar={filtrelenmisSonuclar}
      aktifSozlukler={aktifSozlukler}
      wordsCount={428679}
    />
  );
}