import React, { useEffect, useRef } from "react";
import Image from "next/image";
import { GruplanmisKelime } from "@/types/dictionary";
import { tanimlariBicimlendir, kaynagiDuzenle, type TemaTipi } from "@/utils/helpers";

interface KelimeDetayDrawerProps {
  seciliKelime: GruplanmisKelime;
  kapat: () => void;
  tema: TemaTipi;
  metinBoyutu: number;
}

export default function KelimeDetayDrawer({ seciliKelime, kapat, tema, metinBoyutu }: KelimeDetayDrawerProps) {
  const drawerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") kapat();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [kapat]);

  return (
    <div 
      className="fixed inset-0 z-50 bg-black/50 flex justify-end transition-opacity"
      onClick={kapat}
      role="dialog"
      aria-modal="true"
    >
      <div 
        ref={drawerRef}
        className="w-full max-w-md h-full p-6 overflow-y-auto shadow-xl flex flex-col"
        style={{ backgroundColor: tema.kartArkaPlan }}
        onClick={(e) => e.stopPropagation()}
      >
        <header className="flex justify-between items-center mb-6 pb-4 border-b" style={{ borderColor: tema.kenarlik }}>
          <h2 style={{ color: tema.yaziAna, margin: 0, fontSize: `${metinBoyutu * 1.3}px`, fontWeight: "bold" }}>
            {seciliKelime.kelime}
          </h2>
          <button 
            onClick={kapat} 
            className="px-3 py-2 rounded-md border text-sm hover:opacity-80 transition-opacity"
            style={{ borderColor: tema.kenarlik, color: tema.yaziAna }}
          >
            ✕ Kapat
          </button>
        </header>

        <div className="flex-1 space-y-6">
          {seciliKelime.kaynaklar.map((item: any, index: number) => (
            <article key={index} className="pb-4 border-b last:border-0" style={{ borderColor: tema.kenarlik }}>
              {tanimlariBicimlendir(
                item.tanim, 
                tema, 
                seciliKelime.kelime, 
                metinBoyutu, 
                kaynagiDuzenle(item.file || item.kaynak_sozluk)
              )}
            </article>
          ))}
        </div>

        <footer className="mt-8 pt-4 border-t flex justify-end opacity-90" style={{ borderColor: tema.kenarlik }}>
          <Image 
            src="/imza.png" 
            alt="Açık Mektep Kurumsal İmza" 
            width={120} 
            height={40} 
            className="object-contain"
          />
        </footer>
      </div>
    </div>
  );
}